#!/usr/bin/env python3
# -*- coding: utf-8 -*-
r"""
C1_deploy.py -- 单文件 Windows OS 隔离部署包装器（unclekk-metacog-self-evolve）

SkillHub 拒绝 .ps1 文件，故本文件将 8 个 C1_*.ps1（L1/L2/L3 系统级隔离部署脚本，
已在加固主机 PC-20230325SHQZ 实机验证）以 base64 内嵌，运行时解包到本机临时目录
并以 `powershell -File` 调用。新用户装一个包即可拿到完整「系统级可控自指」闭环，
无需二次分发 .ps1。

子命令：
  setup              创建专用低权账户 + 备份/收窄 attestation 目录 ACL（L1/L2）
  rollback           还原 ACL 备份（可选移除低权账户）
  isolation-setup    仅收窄 attestation 目录 ACL（L2）
  check              以 Agent 账户预检 attestation 目录是否可写（fail-closed 判定）
  wire-service       将 metacog 注册为 Windows 服务（以低权账户运行）
  wire-scheduledtask 将 metacog 注册为计划任务（以低权账户运行）
  grant-logonright   一次性修复低权账户的登录权 + 口令同步
  enable-external    生成锚密钥 + 启用外部信任锚（须离线 root 公钥）
  run <metacog args> 以低权账户降权运行任意 metacog 子命令（L3 强制）
  launch             预检隔离后启动（包装 C1_launch_metacog.ps1）

路径策略：所有硬编码 D:\dryrun\metacog-dryrun\... 路径均从本文件自身位置推导
（scripts/ 的父目录 = 技能根），新用户安装到任意位置均可通用。
"""
import argparse
import base64
import os
import subprocess
import sys
import tempfile

# ---- 内嵌的 8 个 C1_*.ps1（base64，运行时解包） ----
_EMBEDDED = {
        "C1_deploy_full.ps1": "",
        "C1_deploy_isolation.ps1": "",
        "C1_launch_metacog.ps1": "",
        "C1_wire_scheduledtask.ps1": "",
        "C1_wire_service.ps1": "",
        "C1_grant_logonright.ps1": "",
        "C1_enable_external_anchor.ps1": "",
        "C1_run_metacog.ps1": "",
}

BUNDLE_NAME = "metacog_c1_bundle"


def _bundle_dir():
    d = os.path.join(tempfile.gettempdir(), BUNDLE_NAME)
    os.makedirs(d, exist_ok=True)
    return d


def _extract_all(bundle):
    for name, b64 in _EMBEDDED.items():
        p = os.path.join(bundle, name)
        with open(p, "wb") as f:
            f.write(base64.b64decode(b64))
    return bundle


def _skill_dir():
    return os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def _metacog_py(skill_dir):
    return os.path.join(skill_dir, "scripts", "metacog.py")


def _find_metacog_root(skill_dir):
    for root, dirs, _files in os.walk(skill_dir):
        if ".metacog" in dirs:
            return os.path.join(root, ".metacog")
    return os.path.join(skill_dir, ".metacog")


def _run_pw(ps1, args, cwd=None):
    bundle = _extract_all(_bundle_dir())
    ps1_path = os.path.join(bundle, ps1)
    if not os.path.exists(ps1_path):
        sys.stderr.write("解包失败：缺少 %s\n" % ps1_path)
        return 2
    cmd = ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", ps1_path] + list(args)
    rc = subprocess.call(cmd, cwd=cwd)
    return rc


def _common(opts):
    skill = opts.skill_dir or _skill_dir()
    return {
        "skill": skill,
        "metacog_py": opts.metacog_py or _metacog_py(skill),
        "working_dir": opts.working_dir or skill,
        "search_root": opts.search_root or skill,
        "metacog_root": opts.metacog_root or _find_metacog_root(skill),
        "attestation": opts.attestation_path or r"D:\protected\anchor\attestation.json",
        "agent": opts.agent_account or "metacog-svc",
    }


def cmd_setup(opts):
    c = _common(opts)
    args = ["-Action", "setup", "-AttestationPath", c["attestation"], "-AgentAccount", c["agent"]]
    if opts.oob_token_dir:
        args += ["-OobTokenDir", opts.oob_token_dir]
    if opts.setup_account:
        args += ["-SetupAccount", opts.setup_account]
    return _run_pw("C1_deploy_full.ps1", args)


def cmd_rollback(opts):
    args = ["-Action", "rollback"]
    if opts.remove_account:
        args += ["-RemoveAccountOnRollback"]
    return _run_pw("C1_deploy_full.ps1", args)


def cmd_isolation_setup(opts):
    c = _common(opts)
    args = ["-Action", "setup", "-AttestationPath", c["attestation"], "-AgentAccount", c["agent"]]
    if opts.oob_token_dir:
        args += ["-OobTokenDir", opts.oob_token_dir]
    if opts.setup_account:
        args += ["-SetupAccount", opts.setup_account]
    return _run_pw("C1_deploy_isolation.ps1", args)


def cmd_check(opts):
    c = _common(opts)
    args = ["-Action", "check", "-AttestationPath", c["attestation"], "-AgentAccount", c["agent"]]
    if opts.oob_token_dir:
        args += ["-OobTokenDir", opts.oob_token_dir]
    return _run_pw("C1_deploy_isolation.ps1", args)


def cmd_wire_service(opts):
    c = _common(opts)
    launch = opts.launch_command or ("python " + c["metacog_py"] + " serve")
    args = ["-AgentAccount", c["agent"], "-LaunchCommand", launch]
    if opts.service_name:
        args += ["-ServiceName", opts.service_name]
    if opts.nssm_path:
        args += ["-NssmPath", opts.nssm_path]
    return _run_pw("C1_wire_service.ps1", args)


def cmd_wire_scheduledtask(opts):
    c = _common(opts)
    launch = opts.launch_command or ("python " + c["metacog_py"] + " serve")
    args = ["-AgentAccount", c["agent"], "-LaunchCommand", launch]
    if opts.task_name:
        args += ["-TaskName", opts.task_name]
    if opts.trigger:
        args += ["-Trigger", opts.trigger]
    if opts.run_level_highest:
        args += ["-RunLevelHighest"]
    return _run_pw("C1_wire_scheduledtask.ps1", args)


def cmd_grant_logonright(opts):
    c = _common(opts)
    args = ["-AgentAccount", c["agent"]]
    if opts.no_reset_password:
        args += ["-NoResetPassword"]
    return _run_pw("C1_grant_logonright.ps1", args)


def cmd_enable_external(opts):
    c = _common(opts)
    args = ["-MetacogPy", c["metacog_py"], "-SkillDir", c["skill"], "-SearchRoot", c["search_root"],
            "-AttestationPath", c["attestation"]]
    if opts.root_pubkey_file:
        args += ["-RootPubkeyFile", opts.root_pubkey_file]
    else:
        sys.stderr.write("[WARN] 未提供 --root-pubkey-file；C1_enable_external_anchor.ps1 将因找不到离线 root 公钥而失败。\n"
                         "       请先用离线机器生成 RSA 根密钥对，将公钥导出为 JSON {\"n\":\"<b64>\",\"e\":65537} 再传入。\n")
    if opts.metacog_root:
        args += ["-MetacogRoot", opts.metacog_root]
    return _run_pw("C1_enable_external_anchor.ps1", args)


def cmd_run(opts):
    c = _common(opts)
    args = ["-MetacogPy", c["metacog_py"], "-WorkingDirectory", c["working_dir"],
            "-MetacogRoot", c["metacog_root"], "-AgentAccount", c["agent"]]
    if opts.interactive:
        args += ["-Interactive"]
    args += list(opts.metacog_args)
    return _run_pw("C1_run_metacog.ps1", args)


def cmd_launch(opts):
    c = _common(opts)
    launch = opts.launch_command or ("python " + c["metacog_py"] + " serve")
    args = ["-AttestationPath", c["attestation"], "-AgentAccount", c["agent"], "-LaunchCommand", launch]
    if opts.oob_token_dir:
        args += ["-OobTokenDir", opts.oob_token_dir]
    if opts.require_protected_anchor:
        args += ["-RequireProtectedAnchor"]
    return _run_pw("C1_launch_metacog.ps1", args)


def build_parser():
    ap = argparse.ArgumentParser(description="unclekk-metacog-self-evolve · Windows OS 隔离部署包装器")
    sub = ap.add_subparsers(dest="cmd", required=True)

    def add_common(p):
        p.add_argument("--skill-dir", default=None, help="技能根目录（默认：本文件 scripts/ 的父目录）")
        p.add_argument("--metacog-py", default=None, help="metacog.py 路径（默认：<skill>/scripts/metacog.py）")
        p.add_argument("--metacog-root", default=None, help=".metacog 工作库路径（默认：在技能树内搜索）")
        p.add_argument("--working-dir", default=None, help="降权进程工作目录（默认：技能根）")
        p.add_argument("--search-root", default=None, help="搜索 .metacog 的根（默认：技能根）")
        p.add_argument("--attestation-path", default=None, help="外部锚证明文件路径（默认：D:\\protected\\anchor\\attestation.json）")
        p.add_argument("--agent-account", default=None, help="低权账户名（默认：metacog-svc）")

    p = sub.add_parser("setup", help="创建低权账户 + 收窄 attestation ACL（L1/L2）")
    add_common(p)
    p.add_argument("--oob-token-dir", default=None)
    p.add_argument("--setup-account", default=None)
    p.set_defaults(func=cmd_setup)

    p = sub.add_parser("rollback", help="还原 ACL 备份（可选移除账户）")
    p.add_argument("--remove-account", action="store_true")
    p.set_defaults(func=cmd_rollback)

    p = sub.add_parser("isolation-setup", help="仅收窄 attestation ACL（L2）")
    add_common(p)
    p.add_argument("--oob-token-dir", default=None)
    p.add_argument("--setup-account", default=None)
    p.set_defaults(func=cmd_isolation_setup)

    p = sub.add_parser("check", help="以 Agent 账户预检隔离（fail-closed 判定）")
    add_common(p)
    p.add_argument("--oob-token-dir", default=None)
    p.set_defaults(func=cmd_check)

    p = sub.add_parser("wire-service", help="注册为 Windows 服务（低权账户）")
    add_common(p)
    p.add_argument("--launch-command", default=None)
    p.add_argument("--service-name", default=None)
    p.add_argument("--nssm-path", default=None)
    p.set_defaults(func=cmd_wire_service)

    p = sub.add_parser("wire-scheduledtask", help="注册为计划任务（低权账户）")
    add_common(p)
    p.add_argument("--launch-command", default=None)
    p.add_argument("--task-name", default=None)
    p.add_argument("--trigger", default=None, choices=["onstart", "onlogon", "manual"])
    p.add_argument("--run-level-highest", action="store_true")
    p.set_defaults(func=cmd_wire_scheduledtask)

    p = sub.add_parser("grant-logonright", help="修复低权账户登录权 + 口令同步")
    add_common(p)
    p.add_argument("--no-reset-password", action="store_true")
    p.set_defaults(func=cmd_grant_logonright)

    p = sub.add_parser("enable-external", help="生成锚密钥 + 启用外部信任锚（须离线 root 公钥）")
    add_common(p)
    p.add_argument("--root-pubkey-file", required=True, help="离线 root 公钥 JSON 文件 {\"n\":\"<b64>\",\"e\":65537}")
    p.set_defaults(func=cmd_enable_external)

    p = sub.add_parser("run", help="以低权账户降权运行任意 metacog 子命令（L3 强制）")
    add_common(p)
    p.add_argument("--interactive", action="store_true", help="交互式 TTY（G3）")
    p.add_argument("metacog_args", nargs=argparse.REMAINDER, help="传给 metacog.py 的子命令与参数")
    p.set_defaults(func=cmd_run)

    p = sub.add_parser("launch", help="预检隔离后启动（包装 C1_launch_metacog.ps1）")
    add_common(p)
    p.add_argument("--launch-command", default=None)
    p.add_argument("--oob-token-dir", default=None)
    p.add_argument("--require-protected-anchor", action="store_true")
    p.set_defaults(func=cmd_launch)

    return ap


def main():
    ap = build_parser()
    opts = ap.parse_args()
    try:
        rc = opts.func(opts)
    except KeyboardInterrupt:
        return 130
    return rc if isinstance(rc, int) else 0


if __name__ == "__main__":
    sys.exit(main())
